import {beginBottomDialogue} from './bottom-dialogue.js';
import {ULTIMATE_CINEMATIC_STEPS,cinematicSteps} from '../engine/ultimate-rules.js';
import {ICHIGO_META} from './ichigo-meta.js';
import {ichigoPose} from '../characters/ichigo.js';
import {personalCaster} from '../engine/personal-ultimate.js';
import {drawProjectileEnergy} from './projectile-energy.js';
// Use full padded frames and their actual pivots; never reuse the old 320x224 crop.
export function ichigoSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const im=images[key],m=ICHIGO_META[key];if(!im?.complete||!im.naturalWidth)return;const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,Math.min(m.columns-1,Math.max(0,col))*w,Math.min(m.rows-1,Math.max(0,row))*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawIchigoActor(ctx,images,d,f,hurt=false,poseOverride=null){const a=personalCaster(d,f),release=d.personalUltimate?.attack,intro=f.introAge!=null,pose=a?{row:12,frame:Math.min(3,Math.floor((d.personalUltimate.cinematic?.elapsed??d.tick-a.born)/15))}:release?.ownerUid===f.uid&&release.phase==='travel'&&d.tick-release.launch<36?{row:13,frame:Math.min(3,Math.floor((d.tick-release.launch)/9))}:poseOverride||ichigoPose(f,hurt);if(f.state==='defeat')pose.frame=Math.min(3,Math.floor(Math.max(f.age,(d.tick-(f.deathTick??d.tick))/60)*10));ichigoSprite(ctx,images,intro?'ichigo_intro':'ichigo',pose.row,pose.frame,f.x,f.y,.86,0,f.face);}
export function drawIchigoEffects(ctx,images,d,clock){for(const f of d.fighters)if(f.id==='ichigo'&&f.hp>0){if(f.introAge!=null){const p=f.introAge/2.5;if(p>.35){ichigoSprite(ctx,images,'ichigo_intro_vfx',0,Math.floor(p*4),f.x,f.y-55,.8);ichigoSprite(ctx,images,'ichigo_intro_vfx',1,Math.floor(p*4),f.x,f.y,.8);}}else if(d.tick<f.hollowEnd||f.state==='hollowmask'){ctx.save();ctx.globalAlpha=.65;ichigoSprite(ctx,images,'ichigo_vfx',3,Math.floor(clock*9)%4,f.x,f.y-50,.8);ctx.restore();}if(['getsuga','shunpo','bankaislash'].includes(f.state)&&f.age<.55)ichigoSprite(ctx,images,'ichigo_vfx',f.state==='getsuga'?0:f.state==='shunpo'?1:2,0,f.x+f.face*30,f.y-40,.45,0,f.face);}}
export function drawIchigoUltimateWorld(ctx,images,d,clock,reduced){const a=d.personalUltimate?.attack;if(!a||(a.kind&&a.kind!=='fullgetsuga'))return;if(a.phase==='warning'){const endX=a.x+a.dx*1800,endY=a.y+a.dy*1800;ctx.save();ctx.strokeStyle='#ff365b';ctx.globalAlpha=.2+.2*Math.sin(clock*15)**2;ctx.lineWidth=170;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(endX,endY);ctx.stroke();ctx.globalAlpha=.8;ctx.lineWidth=2;ctx.setLineDash([16,12]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(endX,endY);ctx.stroke();ctx.restore();ichigoSprite(ctx,images,'ichigo_ultimate_vfx',0,Math.min(1,Math.floor((d.tick-a.born)/18)),a.x,a.y-50,.8);}}
export function drawIchigoShot(ctx,images,s,x,y,clock,reduced=false){const ultimate=s.kind==='fullgetsuga',key=ultimate?'ichigo_ultimate_vfx':'ichigo_vfx';ichigoSprite(ctx,images,key,0,ultimate?3:2,x,y,ultimate?.85:.4,Math.atan2(s.vy,s.vx));if(ultimate)drawProjectileEnergy(ctx,s,{x,y},clock,{reduced,profile:{radius:75,length:250,color:'#ff234a',accent:'#ffb2c0',dark:true,lightning:5}});}
export function drawIchigoCinematic(ctx,images,d,reduced){const c=d.personalUltimate?.cinematic,a=d.personalUltimate?.attack;if(((c||a)?.kind&&(c||a).kind!=='fullgetsuga'))return;if(!c){if(a?.phase==='travel'&&d.tick-a.launch<48){ctx.save();ctx.globalAlpha=Math.min(1,(48-(d.tick-a.launch))/12);ichigoSprite(ctx,images,'ichigo_dialogue',3,0,480,95,.6);ctx.restore();}return;}const p=c.elapsed/cinematicSteps(c);beginBottomDialogue(ctx,'ichigo');ctx.globalAlpha=Math.min(1,p*8,(1-p)*12);const slide=reduced?0:Math.max(0,1-p*8)*90;ichigoSprite(ctx,images,'ichigo_dialogue',0,p>.4?1:0,480+slide,310,.85);ichigoSprite(ctx,images,'ichigo_dialogue',2,p>.5?1:0,205+slide,310,.25);ctx.textAlign='left';ctx.fillStyle='#fff4f5';ctx.font='bold 22px Segoe UI';ctx.fillText('ICHIGO KUROSAKI',345+slide,260,230);ctx.font='bold 36px Georgia';ctx.fillText('This is everything I’ve got!',345+slide,320,510);ctx.font='bold 20px Segoe UI';ctx.fillStyle='#ff728b';ctx.fillText('BANKAI  /  FULL POWER',345+slide,350,400);ctx.restore();}
